#!/usr/bin/env python3
"""FS3 v170 - Shivan cycle, block B part 2: missions 71 to 75, and fixes
to 67 to 70.

    BEFORE YOU RUN THIS: images/subspace_a.webp and images/subspace_b.webp
    must be on the server (fs3_subspace.zip), or build.sh stops.

    M71       The Reactor Scan: in a Ptah - nothing sees, locks or aims at
              her except for 3 s after she fires. Scan the Lucifer's five
              reactors.
    M72       The Escort: TAG her escort cruisers for the Hatshepsut. From
              here Shivan beams find their targets in the nebula.
    M73       The Bomber Run: our bombers against two cruisers; their point
              defence stops the bombs until the weapons are out.
    M74       The Breakthrough: the Lucifer drives across from right to
              left and is through; hit her escort meanwhile.
    M75       Subspace (boss): no shields for anybody, no support. Only the
              reactors can be hurt; the last one ends her in a run of
              blasts, a great wave and a white-out.
    Fixes     (Silvio, v169) a missile or bomb sometimes struck as a plain
              bolt - the TAG then marked nothing; a tagged miner could not
              be hurt by our beams; a tagged Lucifer draws the beams (onto
              her shield); the Lucifer fires in M69; an Azrael leaves the
              Iceni in M70 and its jump no longer flashes; the Iceni is
              scuttled after the rescue.
    Blasts    the big-blast hulls (gas miners, Faustus, comm node) burn for
              1.5 s before the wave; fighters and bombers of both sides get
              out of any big blast zone.

Needs v169. Edits src/00_head.html and src/20_render.js to src/70_ui.js in
place, and writes the updated fieldsim.js, ramsim.js and pausesim.js. Run
assemble.py afterwards.
"""
import base64
import os
import sys

if "TAG_TIME" not in open("src/50_combat.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v169 einspielen.")
if "PTAH_SEEN" in open("src/50_combat.js", encoding="utf-8").read():
    sys.exit("Abbruch: v170 ist schon eingespielt.")
for _img in ("images/subspace_a.webp", "images/subspace_b.webp"):
    if not os.path.isfile(_img):
        sys.exit("Abbruch: %s fehlt. Erst fs3_subspace.zip nach images/ entpacken." % _img)

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)

